package live.linghe.privateinput;
public final class InputThemeParityTest {
 static int checks;static void ok(boolean b,String label){checks++;if(!b)throw new AssertionError(label);}
 public static void main(String[] args){ok(InputTheme.dark("system",true)&&!InputTheme.dark("system",false),"system follows device");ok(InputTheme.dark("dark",false)&&!InputTheme.dark("light",true),"explicit mode override");ok(InputTheme.index(InputTheme.ACCENTS,"unknown")==0,"unknown accent falls back rose");for(boolean dark:new boolean[]{false,true})for(String accent:InputTheme.ACCENTS){int fg=InputTheme.text(dark),bg=InputTheme.background(dark),key=InputTheme.key(dark),rail=InputTheme.rail(dark),selected=InputTheme.selection(accent,dark),action=InputTheme.accent(accent,dark);ok(InputTheme.contrast(fg,bg)>=7,"main text contrast "+accent+dark);ok(InputTheme.contrast(fg,key)>=7,"key contrast "+accent+dark);ok(InputTheme.contrast(fg,selected)>=4.5,"selected text contrast "+accent+dark);ok(InputTheme.contrast(action,key)>=4.5,"accent action contrast "+accent+dark);ok(InputTheme.contrast(InputTheme.secondary(dark),bg)>=4.5,"secondary text contrast "+accent+dark);ok(InputTheme.contrast(fg,rail)>=7,"rail text contrast "+accent+dark);}System.out.println("PASS "+checks+" Android theme checks");}
}
